  AK_INIT_OR_RETURN();
  Sink_ChunkElement sink;
  sink.out = out;
  sink.base = b;
  int32_t rc = ak_parse_ChunkElement(ctx, b, n);
  if (rc < 0) return rc;
  std::vector<int64_t> &toks = t_pull_toks_chunk_element;
  toks.clear();
